@page "/settings"
@using sv_8363c3c8b97e4ffe9516ddc9f935c5eb.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">
                @toastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }

        @switch (activeSection)
        {
            case "Profile":
                <ProfileSection />;
                break;
            case "Notifications":
                <NotificationsSection />;
                break;
            case "Security":
                <SecuritySection />;
                break;
            case "Appearance":
                <AppearanceSection />;
                break;
        }
    </main>
</div>

@* ===== PROFILE SECTION ===== *@
@{
    void ProfileSection()
    {
        <section class="settings-section">
            <h2>Profile Settings</h2>

            <div class="avatar-area">
                <img src="@editAvatarUrl" alt="Avatar" class="avatar-preview" />
                <span class="avatar-url">@editAvatarUrl</span>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="editDisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="editEmail" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="editBio"></textarea>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    }
}

@* ===== NOTIFICATIONS SECTION ===== *@
@{
    void NotificationsSection()
    {
        <section class="settings-section">
            <h2>Notification Preferences</h2>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="editEmailNotifications" />
                    <span class="toggle-switch"></span>
                    Email Notifications
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="editPushNotifications" />
                    <span class="toggle-switch"></span>
                    Push Notifications
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="editWeeklyDigest" />
                    <span class="toggle-switch"></span>
                    Weekly Digest
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @if (allChannels != null)
                {
                    @foreach (var channel in allChannels)
                    {
                        var ch = channel;
                        <label class="channel-item">
                            <input type="checkbox" checked="@IsChannelMuted(ch)"
                                   @onchange="(e) => ToggleChannelMute(ch, (bool)(e.Value ?? false))" />
                            #@ch
                        </label>
                    }
                }
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    }
}

@* ===== SECURITY SECTION ===== *@
@{
    void SecuritySection()
    {
        <section class="settings-section">
            <h2>Security</h2>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="TogglePasswordPanel">
                    <span>Change Password</span>
                    <span class="expand-icon">@(showPasswordPanel ? "▾" : "▸")</span>
                </button>
                @if (showPasswordPanel)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPassword">Current Password</label>
                            <input id="currentPassword" type="password" @bind="currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPassword">New Password</label>
                            <input id="newPassword" type="password" @bind="newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPassword">Confirm Password</label>
                            <input id="confirmPassword" type="password" @bind="confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="two-factor-section">
                <h3>Two-Factor Authentication</h3>
                <div class="status-row">
                    <span class="status-indicator @(twoFactorEnabled ? "enabled" : "disabled")"></span>
                    <span>@(twoFactorEnabled ? "Enabled" : "Disabled")</span>
                    <label class="toggle-label">
                        <input type="checkbox" @bind="twoFactorEnabled" />
                        <span class="toggle-switch"></span>
                    </label>
                </div>
                @if (lastPasswordChange.HasValue)
                {
                    <p class="info-text">Last password change: @lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }
            </div>

            <div class="sessions-section">
                <h3>Active Sessions</h3>
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th>Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (sessions != null)
                        {
                            @foreach (var session in sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != currentSessionId)
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        }
                    </tbody>
                </table>
            </div>

            @if (showRevokeConfirmation)
            {
                <div class="modal-overlay" @onclick="CancelRevoke">
                    <div class="modal" @onclick:stopPropagation="true">
                        <h3>Confirm Session Revocation</h3>
                        <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke?.Device</strong> from <strong>@sessionToRevoke?.Location</strong>?</p>
                        <div class="button-group">
                            <button class="btn btn-danger" @onclick="RevokeSession">Revoke Session</button>
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    }
}

@* ===== APPEARANCE SECTION ===== *@
@{
    void AppearanceSection()
    {
        <section class="settings-section">
            <h2>Appearance</h2>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    <label class="radio-label">
                        <input type="radio" name="theme" value="Light" checked="@(editTheme == "Light")" @onchange='() => editTheme = "Light"' /> Light
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="theme" value="Dark" checked="@(editTheme == "Dark")" @onchange='() => editTheme = "Dark"' /> Dark
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="theme" value="System" checked="@(editTheme == "System")" @onchange='() => editTheme = "System"' /> System
                    </label>
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="Small" checked="@(editFontSize == "Small")" @onchange='() => editFontSize = "Small"' /> Small
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="Medium" checked="@(editFontSize == "Medium")" @onchange='() => editFontSize = "Medium"' /> Medium
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="Large" checked="@(editFontSize == "Large")" @onchange='() => editFontSize = "Large"' /> Large
                    </label>
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="editLanguage">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Chinese">Chinese</option>
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="editCompactMode" />
                    <span class="toggle-switch"></span>
                    Compact Mode
                </label>
            </div>

            <div class="preview-area @GetPreviewClasses()">
                <h4>Live Preview</h4>
                <p class="preview-text">This is how your content will look with the selected settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>A preview of your chosen theme, font size, and layout density.</p>
                </div>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    }
}

@code {
    private string activeSection = "Profile";

    // Toast
    private string? toastMessage;
    private string toastType = "success";
    private System.Threading.Timer? toastTimer;

    // Profile
    private UserProfile? savedProfile;
    private string editDisplayName = "";
    private string editEmail = "";
    private string editAvatarUrl = "";
    private string editBio = "";

    // Notifications
    private bool editEmailNotifications;
    private bool editPushNotifications;
    private bool editWeeklyDigest;
    private List<string> editMutedChannels = new();
    private List<string> allChannels = new() { "general", "random", "off-topic", "announcements", "dev", "design" };

    // Security
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool twoFactorEnabled;
    private DateTime? lastPasswordChange;
    private List<ActiveSession>? sessions;
    private string currentSessionId = "sess-1";
    private bool showRevokeConfirmation;
    private ActiveSession? sessionToRevoke;

    // Appearance
    private string editTheme = "Light";
    private string editFontSize = "Medium";
    private string editLanguage = "English";
    private bool editCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
        await LoadNotifications();
        await LoadSecurity();
        await LoadAppearance();
    }

    private void SetSection(string section)
    {
        activeSection = section;
    }

    // === Profile ===
    private async Task LoadProfile()
    {
        savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfileToEdit(savedProfile);
    }

    private void ApplyProfileToEdit(UserProfile profile)
    {
        editDisplayName = profile.DisplayName;
        editEmail = profile.Email;
        editAvatarUrl = profile.AvatarUrl;
        editBio = profile.Bio;
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(editDisplayName, editEmail, editAvatarUrl, editBio);
        await SettingsService.SaveProfileAsync(updated);
        savedProfile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile != null)
        {
            ApplyProfileToEdit(savedProfile);
        }
    }

    // === Notifications ===
    private async Task LoadNotifications()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        editEmailNotifications = prefs.EmailNotifications;
        editPushNotifications = prefs.PushNotifications;
        editWeeklyDigest = prefs.WeeklyDigest;
        editMutedChannels = new List<string>(prefs.MutedChannels);
    }

    private bool IsChannelMuted(string channel) => editMutedChannels.Contains(channel);

    private void ToggleChannelMute(string channel, bool muted)
    {
        if (muted && !editMutedChannels.Contains(channel))
            editMutedChannels.Add(channel);
        else if (!muted)
            editMutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(editEmailNotifications, editPushNotifications, editWeeklyDigest, new List<string>(editMutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // === Security ===
    private async Task LoadSecurity()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        twoFactorEnabled = settings.TwoFactorEnabled;
        lastPasswordChange = settings.LastPasswordChange;
        sessions = settings.Sessions;
    }

    private void TogglePasswordPanel() => showPasswordPanel = !showPasswordPanel;

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (newPassword != confirmPassword)
        {
            ShowToast("New passwords do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        showPasswordPanel = false;
        lastPasswordChange = DateTime.UtcNow;
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke != null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            sessions = sessions?.Where(s => s.Id != sessionToRevoke.Id).ToList();
            ShowToast($"Session on {sessionToRevoke.Device} revoked.", "success");
        }
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    // === Appearance ===
    private async Task LoadAppearance()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        editTheme = settings.Theme;
        editFontSize = settings.FontSize;
        editLanguage = settings.Language;
        editCompactMode = settings.CompactMode;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{editTheme.ToLower()} preview-font-{editFontSize.ToLower()}";
        if (editCompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(editTheme, editFontSize, editLanguage, editCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "success");
    }

    // === Toast ===
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        toastTimer?.Dispose();
        toastTimer = new System.Threading.Timer(_ =>
        {
            InvokeAsync(() =>
            {
                toastMessage = null;
                StateHasChanged();
            });
        }, null, 3000, Timeout.Infinite);
    }

    private void DismissToast()
    {
        toastMessage = null;
        toastTimer?.Dispose();
    }
}

