+    border-radius: 8px;
+    margin-bottom: 1.5rem;
+    overflow: hidden;
+}
+
+.panel-header {
+    width: 100%;
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 1rem 1.25rem;
+    background: #f8f9fa;
+    border: none;
+    cursor: pointer;
+    font-size: 1rem;
+    font-weight: 500;
+}
+
+.panel-header:hover {
+    background: #e9ecef;
+}
+
+.panel-body {
+    padding: 1.25rem;
+    border-top: 1px solid #e0e0e0;
+}
+
+/* Two Factor */
+.two-factor-section {
+    margin-bottom: 1.5rem;
+}
+
+.status-row {
+    display: flex;
+    align-items: center;
+    gap: 0.75rem;
+}
+
+.status-indicator {
+    width: 10px;
+    height: 10px;
+    border-radius: 50%;
+}
+
+.status-indicator.enabled {
+    background: #28a745;
+}
+
+.status-indicator.disabled {
+    background: #dc3545;
+}
+
+.info-text {
+    font-size: 0.85rem;
+    color: #666;
+    margin-top: 0.5rem;
+}
+
+/* Sessions Table */
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    margin-top: 0.5rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+.sessions-table th {
+    background: #f8f9fa;
+    font-weight: 600;
+    font-size: 0.85rem;
+    color: #555;
+    text-transform: uppercase;
+}
+
+.current-badge {
+    background: #e7f1ff;
+    color: #0d6efd;
+    padding: 0.2rem 0.6rem;
+    border-radius: 4px;
+    font-size: 0.8rem;
+    font-weight: 500;
+}
+
+/* Modal */
+.modal-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1001;
+}
+
+.modal {
+    background: white;
+    padding: 2rem;
+    border-radius: 12px;
+    max-width: 450px;
+    width: 90%;
+    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
+}
+
+.modal h3 {
+    margin-top: 0;
+}
+
+/* Radio Group */
+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+}
+
+.radio-label {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+}
+
+/* Preview Area */
+.preview-area {
+    margin-top: 1.5rem;
+    padding: 1.5rem;
+    border: 2px dashed #dee2e6;
+    border-radius: 8px;
+    transition: all 0.3s;
+}
+
+.preview-area h4 {
+    margin-top: 0;
+    margin-bottom: 0.75rem;
+}
+
+.preview-card {
+    background: #f8f9fa;
+    padding: 1rem;
+    border-radius: 6px;
+    margin-top: 0.75rem;
+}
+
+/* Theme previews */
+.preview-theme-dark {
+    background: #1a1a2e;
+    color: #e0e0e0;
+    border-color: #444;
+}
+
+.preview-theme-dark .preview-card {
+    background: #2d2d44;
+    color: #ccc;
+}
+
+.preview-theme-light {
+    background: #ffffff;
+    color: #333;
+}
+
+.preview-theme-system {
+    background: #f0f4f8;
+    color: #2d3748;
+    border-color: #a0aec0;
+}
+
+.preview-theme-system .preview-card {
+    background: #edf2f7;
+}
+
+/* Font size previews */
+.preview-font-small {
+    font-size: 0.8rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.2rem;
+}
+
+/* Compact preview */
+.preview-compact {
+    padding: 0.75rem;
+    line-height: 1.3;
+}
+
+.preview-compact .preview-card {
+    padding: 0.5rem;
+    margin-top: 0.4rem;
+}
+

